try { const b = $('Validate Brief').first().json.brief; brand = b.brand_name; code = b.client_code; } catch(e) {}
return [{ json: { brand_name: brand, client_code: code, error_message: err.error?.message || err.message || 'Unknown', error_node: err.error?.node?.name || 'Unknown', created_at: new Date().toISOString() } }];

const data = $input.first().json;
const brief = data.brief;
const project_id = data.project_id;
const apiKey = 'b183c082b67f0971673dbab7ce0a14883f75e5012d09720d17c540efce67bc39';

const queries = data.search_queries;
const allResults = {};

for (const sq of queries) {
  let url;
  if (sq.engine === 'youtube') {
    url = `https://serpapi.com/search.json?engine=youtube&search_query=${encodeURIComponent(sq.search_query)}&api_key=${apiKey}`;
  } else if (sq.engine === 'google_videos') {
