// Strip Gemini artifacts
let clean = rawText
  .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/m, '')
  .replace(/\s*```\s*$/m, '')
  .trim();

let strategies = [];

// Method 1: Direct parse
try {
  const parsed = JSON.parse(clean);
  strategies = parsed.strategies || [parsed];
} catch(e1) {
  // Method 2: Find strategies block
  const match = clean.match(/\{\s*"strategies"\s*:\s*\[[\s\S]*\]\s*\}/);
  if (match) {
    try {
      strategies = JSON.parse(match[0]).strategies || [];
    } catch(e2) { /* fall through */ }
  }

  // Method 3: Extract individual strategy objects
  if (strategies.length === 0) {
    const stratRegex = /\{\s*"strategy_name"\s*:\s*"[^"]+"\s*,[\s\S]*?"concepts"\s*:\s*\[[\s\S]*?\]\s*\}/g;
    let m;
    while ((m = stratRegex.exec(clean)) !== null) {
      try { strategies.push(JSON.parse(m[0])); } catch(e) {}
    }
  }

  // Method 4: Regex extraction of individual concept objects if all else fails
  if (strategies.length === 0) {
    const conceptRegex = /\{[^{}]*"concept_name"\s*:\s*"[^"]+"[^{}]*\}/g;
    const concepts = [];
    let cm;
    while ((cm = conceptRegex.exec(clean)) !== null) {
      try { concepts.push(JSON.parse(cm[0])); } catch(e) {}
    }
    if (concepts.length > 0) {
      // Split into 3 roughly equal groups
      const third = Math.ceil(concepts.length / 3);
      strategies = [
        { strategy_name: 'A', strategy_approach: 'Performance-Focused', rationale: 'Recovered from parse', concepts: concepts.slice(0, third) },
        { strategy_name: 'B', strategy_approach: 'Trend-Focused', rationale: 'Recovered from parse', concepts: concepts.slice(third, third*2) },
        { strategy_name: 'C', strategy_approach: 'Insight-Focused', rationale: 'Recovered from parse', concepts: concepts.slice(third*2) }
      ];
    }
  }
}

// Fallback: single strategy with minimal concept
