  const concepts = s.concepts || [];
  return `=== STRATEGY ${s.strategy_name || String.fromCharCode(65+i)}: ${s.strategy_approach || 'Unknown'} ===
Rationale: ${s.rationale || 'N/A'}
Concepts (${concepts.length}):
${concepts.map((c, j) => `  ${j+1}. "${c.concept_name}" (${c.framework}/${c.hook_type}) — Hook: "${c.hook_text}" — Format: ${c.format} — Funnel: ${c.funnel_stage} — Virality: ${c.virality_score}/10 — Trend: ${c.trend_reference || 'N/A'}`).join('\n')}`;
}).join('\n\n');

const evalPrompt = `You are a senior Creative Director evaluating 3 strategy proposals for ${brief.brand_name}.

== CLIENT CONTEXT ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature}
Target: ${brief.target_user}
Problem: ${brief.biggest_problem}
Differentiator: ${brief.differentiator}
Brand Personality: ${brief.brand_personality}
Compliance: ${brief.compliance || 'None'}
Do NOT Say: ${brief.do_not_say || 'None'}

== STRATEGIES TO EVALUATE ==
${strategySummaries}

== EVALUATION CRITERIA (score each 1-10) ==
1. concept_uniqueness — How different are these from typical generic UGC concepts? Are the names brand-specific? Could these names ONLY work for ${brief.brand_name}?
2. brief_alignment — How well do concepts match the client brief, brand voice, compliance rules, and "do not say" list?
3. audience_resonance — Will the target audience (${brief.target_user}) actually care? Are the pain points and hooks relevant to THEM?
4. production_feasibility — Can a single UGC creator film all these concepts with minimal props/setup? Are the formats realistic?
5. hook_potential — Do the hooks grab attention in under 2 seconds? Are they under 8 words? Do they create an irresistible curiosity gap?

For each criterion, also note specific weaknesses found (to guide a potential retry).

Output ONLY valid JSON:
\`\`\`json
{
  "evaluations": [
    {
      "strategy_name": "A",
      "scores": {
        "concept_uniqueness": 7,
        "brief_alignment": 8,
        "audience_resonance": 6,
        "production_feasibility": 9,
        "hook_potential": 7
      },
      "total": 37,
      "strengths": "What's great about this strategy",
      "weaknesses": "Specific issues to fix",
      "best_concepts": ["name1", "name2"]
    }
  ],
  "winner": "A",
  "overall_feedback": "Summary of what the winning strategy does well and what could still improve"
}
\`\`\`

Be HARSH on generic concept names. If a concept name could apply to any brand, score concept_uniqueness below 5.
Be STRICT on hooks over 8 words — score hook_potential below 4 for strategies with multiple long hooks.

Output ONLY valid JSON.`;

const requestBody = {
  systemInstruction: { parts: [{ text: "You are a brutally honest Creative Director who evaluates UGC strategy proposals. You score harshly but fairly. Generic concept names get destroyed. Long hooks get penalized. You care about what ACTUALLY converts, not what sounds clever in a deck." }] },
  contents: [{ role: "user", parts: [{ text: evalPrompt }] }],
  generationConfig: { temperature: 0.2, maxOutputTokens: 4096 }
};

return [{ json: { requestBody, strategies, brief: data.brief, project_id: data.project_id, numConcepts: data.numConcepts, refVideoList: data.refVideoList, brandVoiceDna: data.brandVoiceDna, systemLearningsText: data.systemLearningsText, raw_output: data.raw_output } }];

// ============================================================
// Select Best Strategy — pick highest score, apply quality gate
// Threshold: 35/50 (70%). If below, set needs_retry = true
// ============================================================

const response = $input.first().json;
let evalText = '';
try {
  evalText = response.candidates[0].content.parts[0].text;
} catch(e) {
  evalText = JSON.stringify(response);
}

// Strip code fences
evalText = evalText
  .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/m, '')
  .replace(/\s*```\s*$/m, '')
  .trim();

let evalResult = {};
try {
  evalResult = JSON.parse(evalText);
} catch(e) {
  const match = evalText.match(/\{[\s\S]*"evaluations"[\s\S]*\}/);
  if (match) {
    try { evalResult = JSON.parse(match[0]); } catch(e2) {}
  }
}

const evaluations = evalResult.evaluations || [];
const prev = $('Build Evaluation Prompt').first().json;
const strategies = prev.strategies;

// Find winner
let bestIdx = 0;
let bestScore = 0;
for (let i = 0; i < evaluations.length; i++) {
  const total = evaluations[i].total || Object.values(evaluations[i].scores || {}).reduce((a,b) => a+b, 0);
  evaluations[i].total = total;
  if (total > bestScore) {
    bestScore = total;
    bestIdx = i;
  }
}

const winnerName = evaluations[bestIdx]?.strategy_name || evalResult.winner || 'A';
const winnerStrat = strategies.find(s => s.strategy_name === winnerName) || strategies[0];
const winnerEval = evaluations[bestIdx] || {};

const THRESHOLD = 35;
const needs_retry = bestScore < THRESHOLD;

// Build the concepts output (winning strategy's concepts)
const concepts = winnerStrat.concepts || [];

return [{ json: {
  winner_name: winnerName,
  winner_score: bestScore,
  winner_approach: winnerStrat.strategy_approach || 'Unknown',
  needs_retry: needs_retry,
  weaknesses: winnerEval.weaknesses || '',
  overall_feedback: evalResult.overall_feedback || '',
  evaluation_raw: evalText,
  concepts,
  brief: prev.brief,
  project_id: prev.project_id,
  numConcepts: prev.numConcepts,
  refVideoList: prev.refVideoList,
  brandVoiceDna: prev.brandVoiceDna,
  systemLearningsText: prev.systemLearningsText,
  strategies_raw: prev.raw_output
} }];

// ============================================================
// Build Retry Prompt with weakness feedback from evaluation
// ============================================================

const data = $input.first().json;
const brief = data.brief;

const retryPrompt = `RETRY: Your previous strategy scored ${data.winner_score}/50 (below our 35/50 quality threshold).

== WEAKNESSES IDENTIFIED ==
${data.weaknesses || 'No specific weaknesses identified.'}

== OVERALL FEEDBACK ==
${data.overall_feedback || 'Needs improvement across the board.'}

== ANTI-GENERIC RULES (STRICTLY ENFORCED) ==
- EVERY concept name must be unique to ${brief.brand_name} — no generic names allowed
- ALL hooks must be 8 words or fewer
- Each concept MUST reference a specific trend, format, or cultural moment
- BAD: "The Transformation Story" | GOOD: "My Mechanic's Face When He Saw This"
- BAD: "Social Proof Showcase" | GOOD: "432 One-Star Reviews Changed My Mind"

== CLIENT BRIEF REMINDER ==
Brand: ${brief.brand_name}
Product: ${brief.product_feature}
Differentiator: ${brief.differentiator}
Target: ${brief.target_user}
Problem: ${brief.biggest_problem}

== AVAILABLE REFERENCE VIDEOS ==
${data.refVideoList || 'No reference videos available.'}

== BRAND VOICE DNA ==
${data.brandVoiceDna || 'No brand voice data.'}

${data.systemLearningsText || ''}

Generate ${data.numConcepts} IMPROVED concepts addressing ALL the weaknesses above.
Focus on the areas that scored lowest.

Output ONLY valid JSON with a "concepts" array. Same format as before:
Each concept needs: concept_name, reference_video_url, reference_platform, framework, hook_type, hook_text, format, funnel_stage, virality_score, concept_pitch, emotional_journey, target_objection, platform, ab_test_pair, trend_reference

DIVERSITY: Different framework+hook_type combos, 4+ formats, mixed funnel stages, 1+ A/B pair.
Output ONLY valid JSON.`;

const requestBody = {
  systemInstruction: { parts: [{ text: "You are a UGC Creative Director on your SECOND attempt. Your first batch was rejected for quality issues. This time you MUST fix every weakness identified. Be more creative, more specific, more brand-aligned. No generic concepts allowed. Hooks under 8 words ONLY. Output ONLY valid JSON with a 'concepts' array." }] },
  contents: [{ role: "user", parts: [{ text: retryPrompt }] }],
  generationConfig: { temperature: 0.9, maxOutputTokens: 16384 }
};

return [{ json: { requestBody, brief: data.brief, project_id: data.project_id } }];

