}

const prev = $('Build Retry Prompt').first().json;

return [{ json: { output: rawText, text: rawText, brief: prev.brief, project_id: prev.project_id } }];

// ============================================================
// Format Output B — pass winning strategy concepts as output
// ============================================================

const data = $input.first().json;
const concepts = data.concepts || [];

// Build a JSON string that looks like Gemini's normal output
const output = JSON.stringify({ concepts });

return [{ json: { output, text: output, brief: data.brief, project_id: data.project_id } }];

// Generate a project goal from brief data
const brief = $('Validate Brief').first().json.brief;
const projectRecord = $input.first().json;
const project_id = projectRecord.id || projectRecord.records?.[0]?.id || '';

const goalText = `Create ${brief.num_scripts || 3} high-performing UGC ads for ${brief.brand_name} targeting ${brief.target_user || 'the target audience'}. The ads should demonstrate ${brief.product_feature || 'the product'} and convert viewers by addressing their core pain point: ${brief.biggest_problem || 'unspecified'}. Key differentiator: ${brief.differentiator || brief.selling_proposition || 'unique value proposition'}.`;

return [{ json: { 
  project_id, 
  project_goal: goalText,
  brief,
  ...projectRecord
} }];
